#[derive(Debug, Clone, PartialEq, Default)]
pub struct Condition {
    /// `CTDA`, required.
    pub data: Option<Sub<ConditionData>>,
    /// `CIS1`, optional.
    pub string_parameter1: Option<Sub<ZString>>,
    /// `CIS2`, optional.
    pub string_parameter2: Option<Sub<ZString>>,
}

impl Condition {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"CTDA",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"CIS1",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"CIS2",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.data, subs, *index, "Condition.CTDA", ctx, extra)
                }
                Hit::Sub { member: 1, index } => put(
                    &mut self.string_parameter1,
                    subs,
                    *index,
                    "Condition.CIS1",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 2, index } => put(
                    &mut self.string_parameter2,
                    subs,
                    *index,
                    "Condition.CIS2",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"CTDA", self.data.as_ref());
        emit(out, *b"CIS1", self.string_parameter1.as_ref());
        emit(out, *b"CIS2", self.string_parameter2.as_ref());
    }
}

