#[derive(Debug, Clone, PartialEq)]
pub struct AmmoData {
    pub value: u32,
    /// Present only when bytes remain in the payload.
    pub weight: Option<f32>,
}

impl Field for AmmoData {
    fn read(r: &mut Reader<'_>, _field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        let f0 = u32::read(r, "AMMO.DATA.Value", ctx)?;
        let f1 = if !r.is_empty() {
            Some(f32::read(r, "AMMO.DATA.Weight", ctx)?)
        } else {
            None
        };
        Ok(Self {
            value: f0,
            weight: f1,
        })
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.value.write(out);
        if let Some(value) = &self.weight {
            value.write(out);
        }
    }
}

impl Visit for AmmoData {}

/// Bit flags; bits without a name are preserved.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct AmmoAmmoDataFlags(pub u8);

impl AmmoAmmoDataFlags {
    pub const IGNORES_NORMAL_WEAPON_RESISTANCE: u8 = 0x1;
    pub const NON_PLAYABLE: u8 = 0x2;
    pub const HAS_COUNT_BASED3D: u8 = 0x4;

    /// Whether every bit of `mask` is set.
    pub fn contains(self, mask: u8) -> bool {
        self.0 & mask == mask
    }
}

impl Field for AmmoAmmoDataFlags {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u8::read(r, field, ctx).map(Self)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.0.write(out);
    }
}

impl Visit for AmmoAmmoDataFlags {}

