impl AmmoRecord {
    /// Record signature.
    pub const SIGNATURE: Sig = *b"AMMO";
    /// Record-header flag.
    pub const FLAG_NON_PLAYABLE: u32 = 0x4;
    /// Record-header flag.
    pub const FLAG_GROUND_PIECE: u32 = 0x10;
    /// Record-header flag.
    pub const FLAG_HIDDEN_FROM_LOCAL_MAP: u32 = 0x200;
    /// Record-header flag.
    pub const FLAG_USED_AS_PLATFORM: u32 = 0x800;
    /// Record-header flag.
    pub const FLAG_HAS_CURRENTS: u32 = 0x80000;
    /// Record-header flag.
    pub const FLAG_NAVMESH_FILTER: u32 = 0x4000000;
    /// Record-header flag.
    pub const FLAG_NAVMESH_BOUNDING_BOX: u32 = 0x8000000;
    /// Record-header flag.
    pub const FLAG_NAVMESH_ONLY_CUT: u32 = 0x10000000;
    /// Record-header flag.
    pub const FLAG_NAVMESH_IGNORE_EROSION: u32 = 0x20000000;
    /// Record-header flag.
    pub const FLAG_NAVMESH_GROUND: u32 = 0x40000000;
    /// Record-header flag.
    pub const FLAG_MUST_BE_UNIQUE: u32 = 0x80000000;

    /// Decodes a record body. Never fails: subrecords that match no member or do not
    /// decode are kept in `extra`.
    pub fn decode(subs: &[RawSub<'_>], ctx: Ctx) -> Self {
        let (hits, unmatched_indexes) = match_members(subs, Self::MEMBERS);
        let mut record = Self::default();
        let mut extra = Vec::new();
        for index in unmatched_indexes {
            if let Some(sub) = subs.get(index) {
                extra.push((index, OwnedSub::from(sub)));
            }
        }
        record.fill(&hits, subs, ctx, &mut extra);
        record.extra = extra;
        record
    }

    /// Encodes the record body: typed members in definition order, `extra` re-inserted at
    /// the indexes it was read from.
    pub fn encode(&self) -> Vec<OwnedSub> {
        let mut out = Vec::new();
        self.emit(&mut out);
        merge_extra(out, &self.extra)
    }

    /// Every FormID-typed value (raw, as stored), in definition order, with the path of
    /// the member or field holding it. `extra` and opaque payloads are not visited.
    pub fn form_ids(&self) -> FormIds<'_> {
        let mut out = Vec::new();
        self.visit_form_ids("AMMO", &mut out);
        out
    }

    /// [`Self::form_ids`], mutably (for remapping FormIDs in place).
    pub fn form_ids_mut(&mut self) -> FormIdsMut<'_> {
        let mut out = Vec::new();
        self.visit_form_ids_mut("AMMO", &mut out);
        out
    }

    /// Every lstring value, in definition order, with the path of the member or field
    /// holding it. `extra` and opaque payloads are not visited.
    pub fn lstrings(&self) -> LStrings<'_> {
        let mut out = Vec::new();
        self.visit_lstrings("AMMO", &mut out);
        out
    }

    /// [`Self::lstrings`], mutably (for replacing string IDs with inline text).
    pub fn lstrings_mut(&mut self) -> LStringsMut<'_> {
        let mut out = Vec::new();
        self.visit_lstrings_mut("AMMO", &mut out);
        out
    }
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct AvifLocalizedStrings {
    /// `ANAM`, optional.
    pub abbreviation: Option<Sub<LString>>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
}

impl AvifLocalizedStrings {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"ANAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.abbreviation,
                    subs,
                    *index,
                    "AVIF.LocalizedStrings.ANAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 1, index } => put(
                    &mut self.name,
                    subs,
                    *index,
                    "AVIF.LocalizedStrings.FULL",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"ANAM", self.abbreviation.as_ref());
        emit(out, *b"FULL", self.name.as_ref());
    }
}

impl Visit for AvifLocalizedStrings {
    fn visit_lstrings<'a>(&'a self, _path: &'static str, out: &mut LStrings<'a>) {
        visit_lstrings(&self.abbreviation, "AVIF.LocalizedStrings.ANAM", out);
        visit_lstrings(&self.name, "AVIF.LocalizedStrings.FULL", out);
    }

    fn visit_lstrings_mut<'a>(&'a mut self, _path: &'static str, out: &mut LStringsMut<'a>) {
        visit_lstrings_mut(&mut self.abbreviation, "AVIF.LocalizedStrings.ANAM", out);
        visit_lstrings_mut(&mut self.name, "AVIF.LocalizedStrings.FULL", out);
    }
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct AvifRecord {
    /// `EDID`, optional.
    pub editor_id: Option<Sub<ZString>>,
    /// Group `LocalizedStrings`, repeated.
    pub localized_strings: Vec<AvifLocalizedStrings>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl AvifRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: AvifLocalizedStrings::MEMBERS,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "AVIF.EDID", ctx, extra)
                }
                Hit::Group { member: 1, hits } => {
                    let mut group = AvifLocalizedStrings::default();
                    group.fill(hits, subs, ctx, extra);
                    self.localized_strings.push(group);
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        for group in &self.localized_strings {
            group.emit(out);
        }
    }
}

impl Visit for AvifRecord {
    fn visit_lstrings<'a>(&'a self, _path: &'static str, out: &mut LStrings<'a>) {
        visit_lstrings(&self.localized_strings, "AVIF.LocalizedStrings", out);
    }

    fn visit_lstrings_mut<'a>(&'a mut self, _path: &'static str, out: &mut LStringsMut<'a>) {
        visit_lstrings_mut(&mut self.localized_strings, "AVIF.LocalizedStrings", out);
    }
}

impl AvifRecord {
    /// Record signature.
    pub const SIGNATURE: Sig = *b"AVIF";

    /// Decodes a record body. Never fails: subrecords that match no member or do not
    /// decode are kept in `extra`.
    pub fn decode(subs: &[RawSub<'_>], ctx: Ctx) -> Self {
        let (hits, unmatched_indexes) = match_members(subs, Self::MEMBERS);
        let mut record = Self::default();
        let mut extra = Vec::new();
        for index in unmatched_indexes {
            if let Some(sub) = subs.get(index) {
                extra.push((index, OwnedSub::from(sub)));
            }
        }
        record.fill(&hits, subs, ctx, &mut extra);
        record.extra = extra;
        record
    }

    /// Encodes the record body: typed members in definition order, `extra` re-inserted at
    /// the indexes it was read from.
    pub fn encode(&self) -> Vec<OwnedSub> {
        let mut out = Vec::new();
        self.emit(&mut out);
        merge_extra(out, &self.extra)
    }

    /// Every FormID-typed value (raw, as stored), in definition order, with the path of
    /// the member or field holding it. `extra` and opaque payloads are not visited.
    pub fn form_ids(&self) -> FormIds<'_> {
        let mut out = Vec::new();
        self.visit_form_ids("AVIF", &mut out);
        out
    }

    /// [`Self::form_ids`], mutably (for remapping FormIDs in place).
    pub fn form_ids_mut(&mut self) -> FormIdsMut<'_> {
        let mut out = Vec::new();
        self.visit_form_ids_mut("AVIF", &mut out);
        out
    }

    /// Every lstring value, in definition order, with the path of the member or field
    /// holding it. `extra` and opaque payloads are not visited.
    pub fn lstrings(&self) -> LStrings<'_> {
        let mut out = Vec::new();
        self.visit_lstrings("AVIF", &mut out);
        out
    }

    /// [`Self::lstrings`], mutably (for replacing string IDs with inline text).
    pub fn lstrings_mut(&mut self) -> LStringsMut<'_> {
        let mut out = Vec::new();
        self.visit_lstrings_mut("AVIF", &mut out);
        out
    }
}

