#[derive(Debug, Clone, PartialEq, Default)]
pub struct BiomMask {
    /// `FNAM`, required.
    pub mask_name: Option<Sub<ZString>>,
    /// `BNAM`, required.
    pub bnam: Option<Sub<[u8; 4]>>,
    /// `GNAM`, repeated.
    pub objects: Vec<Sub<BiomMaskObjects>>,
    /// `DNAM`, required.
    pub footprints: Option<Sub<BiomMaskFootprints>>,
}

impl BiomMask {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"FNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"BNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"GNAM",
            card: Card::Repeated,
        },
        MemberDesc::Sub {
            sig: *b"DNAM",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.mask_name,
                    subs,
                    *index,
                    "BIOM.Mask.FNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 1, index } => {
                    put(&mut self.bnam, subs, *index, "BIOM.Mask.BNAM", ctx, extra)
                }
                Hit::Sub { member: 2, index } => push(
                    &mut self.objects,
                    subs,
                    *index,
                    "BIOM.Mask.GNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 3, index } => put(
                    &mut self.footprints,
                    subs,
                    *index,
                    "BIOM.Mask.DNAM",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"FNAM", self.mask_name.as_ref());
        emit(out, *b"BNAM", self.bnam.as_ref());
        for value in &self.objects {
            emit(out, *b"GNAM", Some(value));
        }
        emit(out, *b"DNAM", self.footprints.as_ref());
    }
}

impl Visit for BiomMask {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.objects, "BIOM.Mask.GNAM", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.objects, "BIOM.Mask.GNAM", out);
    }
}

