#[derive(Debug, Clone, PartialEq, Default)]
pub struct BiomMarker {
    /// `KNAM`, required.
    pub marker_type: Option<Sub<FormId>>,
    /// Group `Keywords`, optional.
    pub keywords: Option<Keywords>,
}

impl BiomMarker {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"KNAM",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Keywords::MEMBERS,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.marker_type,
                    subs,
                    *index,
                    "BIOM.Marker.KNAM",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 1, hits } if self.keywords.is_none() => {
                    let mut group = Keywords::default();
                    group.fill(hits, subs, ctx, extra);
                    self.keywords = Some(group);
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"KNAM", self.marker_type.as_ref());
        if let Some(group) = &self.keywords {
            group.emit(out);
        }
    }
}

impl Visit for BiomMarker {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.marker_type, "BIOM.Marker.KNAM", out);
        visit_form_ids(&self.keywords, "BIOM.Marker.Keywords", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.marker_type, "BIOM.Marker.KNAM", out);
        visit_form_ids_mut(&mut self.keywords, "BIOM.Marker.Keywords", out);
    }
}

