#[derive(Debug, Clone, PartialEq, Default)]
pub struct CobjRecord {
    /// `EDID`, required.
    pub editor_id: Option<Sub<ZString>>,
    /// `VMAD`, optional.
    pub scripts: Option<Sub<Bytes>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// `DESC`, required.
    pub description: Option<Sub<LString>>,
    /// `BNAM`, required.
    pub workbench_keyword: Option<Sub<FormId>>,
    /// Group `Conditions`, repeated.
    pub conditions: Vec<Condition>,
    /// `FVPA`, optional.
    pub components: Option<Sub<CobjComponents>>,
    /// `RQPK`, optional.
    pub required_perks: Option<Sub<CobjRequiredPerks>>,
    /// `CNAM`, required.
    pub created_object: Option<Sub<FormId>>,
    /// `NNAM`, required.
    pub amount_produced: Option<Sub<u16>>,
    /// `SNAM`, required.
    pub menu_priority_order: Option<Sub<f32>>,
    /// `TNAM`, required.
    pub tier: Option<Sub<CobjTier>>,
    /// `CUSH`, optional.
    pub crafting_sound: Option<Sub<SoundReference>>,
    /// `PUSH`, optional.
    pub pickup_sound: Option<Sub<SoundReference>>,
    /// `PDSH`, optional.
    pub putdown_sound: Option<Sub<SoundReference>>,
    /// `REPR`, optional.
    pub repair_components: Option<Sub<CobjRepairComponents>>,
    /// `LRNM`, required.
    pub learn_method: Option<Sub<CobjLearnMethod>>,
    /// `DATA`, required.
    pub value: Option<Sub<u32>>,
    /// `ANAM`, optional.
    pub menu_art_object: Option<Sub<FormId>>,
    /// `GNAM`, optional.
    pub learned_from: Option<Sub<FormId>>,
    /// `CVT0`, optional.
    pub base_return_scale_table: Option<Sub<FormId>>,
    /// `LRNC`, optional.
    pub learn_chance: Option<Sub<FormId>>,
    /// `JNAM`, optional.
    pub max_build_count_global: Option<Sub<FormId>>,
    /// `FNAM`, optional.
    pub recipe_filters: Option<Sub<CobjRecipeFilters>>,
    /// `CIFK`, optional.
    pub instanced_filter_keyword: Option<Sub<FormId>>,
    /// `RECF`, required.
    pub recipe_flags: Option<Sub<CobjRecipeFlags>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl CobjRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"VMAD",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"DESC",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"BNAM",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Condition::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"FVPA",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"RQPK",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"CNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"NNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"SNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"TNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"CUSH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PUSH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PDSH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"REPR",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"LRNM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ANAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"GNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"CVT0",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"LRNC",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"JNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"FNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"CIFK",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"RECF",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "COBJ.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scripts, subs, *index, "COBJ.VMAD", ctx, extra)
                }
                Hit::Group { member: 2, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 3, index } => {
                    put(&mut self.name, subs, *index, "COBJ.FULL", ctx, extra)
                }
                Hit::Sub { member: 4, index } => {
                    put(&mut self.description, subs, *index, "COBJ.DESC", ctx, extra)
                }
                Hit::Sub { member: 5, index } => put(
                    &mut self.workbench_keyword,
                    subs,
                    *index,
                    "COBJ.BNAM",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 6, hits } => {
                    let mut group = Condition::default();
                    group.fill(hits, subs, ctx, extra);
                    self.conditions.push(group);
                }
                Hit::Sub { member: 7, index } => {
                    put(&mut self.components, subs, *index, "COBJ.FVPA", ctx, extra)
                }
                Hit::Sub { member: 8, index } => put(
                    &mut self.required_perks,
                    subs,
                    *index,
                    "COBJ.RQPK",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 9, index } => put(
                    &mut self.created_object,
                    subs,
                    *index,
                    "COBJ.CNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 10, index } => put(
                    &mut self.amount_produced,
                    subs,
                    *index,
                    "COBJ.NNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 11, index } => put(
                    &mut self.menu_priority_order,
                    subs,
                    *index,
                    "COBJ.SNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 12, index } => {
                    put(&mut self.tier, subs, *index, "COBJ.TNAM", ctx, extra)
                }
                Hit::Sub { member: 13, index } => put(
                    &mut self.crafting_sound,
                    subs,
                    *index,
                    "COBJ.CUSH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 14, index } => put(
                    &mut self.pickup_sound,
                    subs,
                    *index,
                    "COBJ.PUSH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 15, index } => put(
                    &mut self.putdown_sound,
                    subs,
                    *index,
                    "COBJ.PDSH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 16, index } => put(
                    &mut self.repair_components,
                    subs,
                    *index,
                    "COBJ.REPR",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 17, index } => put(
                    &mut self.learn_method,
                    subs,
                    *index,
                    "COBJ.LRNM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 18, index } => {
                    put(&mut self.value, subs, *index, "COBJ.DATA", ctx, extra)
                }
                Hit::Sub { member: 19, index } => put(
                    &mut self.menu_art_object,
                    subs,
                    *index,
                    "COBJ.ANAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 20, index } => put(
                    &mut self.learned_from,
                    subs,
                    *index,
                    "COBJ.GNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 21, index } => put(
                    &mut self.base_return_scale_table,
                    subs,
                    *index,
                    "COBJ.CVT0",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 22, index } => put(
                    &mut self.learn_chance,
                    subs,
                    *index,
                    "COBJ.LRNC",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 23, index } => put(
                    &mut self.max_build_count_global,
                    subs,
                    *index,
                    "COBJ.JNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 24, index } => put(
                    &mut self.recipe_filters,
                    subs,
                    *index,
                    "COBJ.FNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 25, index } => put(
                    &mut self.instanced_filter_keyword,
                    subs,
                    *index,
                    "COBJ.CIFK",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 26, index } => put(
                    &mut self.recipe_flags,
                    subs,
                    *index,
                    "COBJ.RECF",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"VMAD", self.scripts.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"FULL", self.name.as_ref());
        emit(out, *b"DESC", self.description.as_ref());
        emit(out, *b"BNAM", self.workbench_keyword.as_ref());
        for group in &self.conditions {
            group.emit(out);
        }
        emit(out, *b"FVPA", self.components.as_ref());
        emit(out, *b"RQPK", self.required_perks.as_ref());
        emit(out, *b"CNAM", self.created_object.as_ref());
        emit(out, *b"NNAM", self.amount_produced.as_ref());
        emit(out, *b"SNAM", self.menu_priority_order.as_ref());
        emit(out, *b"TNAM", self.tier.as_ref());
        emit(out, *b"CUSH", self.crafting_sound.as_ref());
        emit(out, *b"PUSH", self.pickup_sound.as_ref());
        emit(out, *b"PDSH", self.putdown_sound.as_ref());
        emit(out, *b"REPR", self.repair_components.as_ref());
        emit(out, *b"LRNM", self.learn_method.as_ref());
        emit(out, *b"DATA", self.value.as_ref());
        emit(out, *b"ANAM", self.menu_art_object.as_ref());
        emit(out, *b"GNAM", self.learned_from.as_ref());
        emit(out, *b"CVT0", self.base_return_scale_table.as_ref());
        emit(out, *b"LRNC", self.learn_chance.as_ref());
        emit(out, *b"JNAM", self.max_build_count_global.as_ref());
        emit(out, *b"FNAM", self.recipe_filters.as_ref());
        emit(out, *b"CIFK", self.instanced_filter_keyword.as_ref());
        emit(out, *b"RECF", self.recipe_flags.as_ref());
    }
}

