    /// Record signature.
    pub const SIGNATURE: Sig = *b"LCTN";
    /// Record-header flag.
    pub const FLAG_NON_PLAYABLE: u32 = 0x4;
    /// Record-header flag.
    pub const FLAG_GROUND_PIECE: u32 = 0x10;
    /// Record-header flag.
    pub const FLAG_HIDDEN_FROM_LOCAL_MAP: u32 = 0x200;
    /// Record-header flag.
