#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProjObjectPaletteDefaultsFootprint {
    ExtraLarge,
    Large,
    Medium,
    Small,
    None,
    /// A value the definition does not name.
    Other(u32),
}

impl ProjObjectPaletteDefaultsFootprint {
    /// The variant for a stored value.
    pub fn from_raw(raw: u32) -> Self {
        match raw {
            0 => Self::ExtraLarge,
            1 => Self::Large,
            2 => Self::Medium,
            3 => Self::Small,
            5 => Self::None,
            other => Self::Other(other),
        }
    }

    /// The stored value.
    pub fn to_raw(self) -> u32 {
        match self {
            Self::ExtraLarge => 0,
            Self::Large => 1,
            Self::Medium => 2,
            Self::Small => 3,
            Self::None => 5,
            Self::Other(raw) => raw,
        }
    }
}

impl Field for ProjObjectPaletteDefaultsFootprint {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u32::read(r, field, ctx).map(Self::from_raw)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.to_raw().write(out);
    }
}

