        emit(out, *b"XATP", self.activation_point.as_ref());
        emit(out, *b"XLIB", self.leveled_item_base.as_ref());
        emit(out, *b"XTV2", self.traversals.as_ref());
        emit(out, *b"XNDP", self.navmesh_door_link.as_ref());
